"use strict";(self.webpackChunkdg_knowlege_base=self.webpackChunkdg_knowlege_base||[]).push([[25624],{96343:e=>{e.exports=JSON.parse('{"tag":{"label":"Schema Change Detection","permalink":"/docs/tags/schema-change-detection","allTagsPath":"/docs/tags","count":1,"items":[{"id":"Lakehouse/Schema change detection","title":"Schema change detection","description":"DataGOL\'s Schema Change Detection feature monitors the source tables involved in your pipelines for any modifications to their structure (e.g., new columns, deleted columns, data type changes). This helps you stay informed about potential impacts on your data pipelines and warehouse. When a schema change is detected, it is recorded, indicating the table, the modified columns, and the nature of the change (e.g., data type, size).","permalink":"/docs/Lakehouse/schema-change-detection"}],"unlisted":false}}')}}]);